// src/commands/totp.ts
init_client2();
init_formatter();
import pc15 from "picocolors";

// src/crypto/totp.ts
import * as crypto from "crypto";
function base32Decode(secret) {
  const clean = secret.toUpperCase().replace(/[\s=-]/g, "");
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  let bits = 0;
  let value = 0;
  const bytes = [];
  for (let i = 0; i < clean.length; i++) {
    const idx = alphabet.indexOf(clean[i]);
    if (idx === -1) continue;
    value = value << 5 | idx;
    bits += 5;
    if (bits >= 8) {
      bytes.push(value >>> bits - 8 & 255);
      bits -= 8;
    }
  }
  return Buffer.from(bytes);
}
function generateTotp(secret, periodSeconds = 30, digits = 6) {
  const key = base32Decode(secret);
  const nowSeconds = Math.floor(Date.now() / 1e3);
  const counter = Math.floor(nowSeconds / periodSeconds);
  const remainingSeconds = periodSeconds - nowSeconds % periodSeconds;
  const counterBuf = Buffer.alloc(8);
  counterBuf.writeBigInt64BE(BigInt(counter));
  const hmac = crypto.createHmac("sha1", key).update(counterBuf).digest();
  const offset = hmac[hmac.length - 1] & 15;
  const binary = (hmac[offset] & 127) << 24 | (hmac[offset + 1] & 255) << 16 | (hmac[offset + 2] & 255) << 8 | hmac[offset + 3] & 255;
  const otp = binary % 10 ** digits;
  const code = String(otp).padStart(digits, "0");
  return { code, remainingSeconds };
}

// src/commands/totp.ts
async function listTotpCommand(opts) {
  try {
    const isAuthed = hasAuth(opts);
    const limit = opts.limit ? parseInt(opts.limit, 10) : 50;
    const session = getVaultSession();
    const items = isAuthed ? await getClient(opts).totp.list({
      limit,
      workspaceId: opts.workspace,
      mek: session?.mekHex
    }) : LocalStore.listTotp();
    if (opts.json) {
      printJson(items);
      return;
    }
    const rows = (items || []).map((t) => {
      let codeDisplay = pc15.dim("locked");
      if (t.secret) {
        try {
          const { code, remainingSeconds } = generateTotp(t.secret);
          codeDisplay = `${pc15.bold(pc15.green(code))} (${remainingSeconds}s)`;
        } catch {
          codeDisplay = pc15.red("invalid secret");
        }
      }
      return {
        id: t.id,
        name: t.name || t.label || "(Untitled TOTP)",
        issuer: t.issuer || "",
        account: t.account || "",
        code: codeDisplay,
        mode: isAuthed ? t.workspaceId || "cloud" : pc15.dim("local")
      };
    });
    printTable(rows, ["id", "name", "issuer", "account", "code", "mode"]);
    if (isAuthed && !session) {
      console.log(pc15.dim("\nTip: Run `kylrix vault unlock` to show live 2FA verification codes."));
    }
  } catch (err) {
    printError("Failed to list TOTP entries", err);
    process.exit(1);
  }
}
async function getTotpCodeCommand(id, opts) {
  try {
    const isAuthed = hasAuth(opts);
    const session = getVaultSession();
    const item = isAuthed ? await getClient(opts).totp.get(id, { mek: session?.mekHex }) : LocalStore.getTotp(id);
    if (!item.secret) {
      throw new Error("Could not decrypt TOTP secret. Please run `kylrix vault unlock` first.");
    }
    const { code, remainingSeconds } = generateTotp(item.secret);
    if (opts.pure) {
      process.stdout.write(code + "\n");
      return;
    }
    console.log(`
  ${pc15.bold(item.name || item.issuer || "2FA Code")}: ${pc15.bold(pc15.green(code))} (${remainingSeconds}s remaining)
`);
  } catch (err) {
    printError(`Failed to generate TOTP code for "${id}"`, err);
    process.exit(1);
  }
}
async function createTotpCommand(name, opts) {
  try {
    const isAuthed = hasAuth(opts);
    const session = getVaultSession();
    const payload = {
      name,
      secret: opts.secret,
      issuer: opts.issuer,
      account: opts.account
    };
    const item = isAuthed ? await getClient(opts).totp.create(payload, {
      mek: session?.mekHex,
      workspaceId: opts.workspace
    }) : LocalStore.createTotp(payload);
    if (opts.json) {
      printJson(item);
      return;
    }
    printSuccess(`Created TOTP seed "${pc15.bold(item.name || item.id)}" (ID: ${item.id}) [${isAuthed ? "Cloud" : "Local"}]`);
  } catch (err) {
    printError("Failed to create TOTP entry", err);
    process.exit(1);
  }
}
async function deleteTotpCommand(id, opts) {
  try {
    const isAuthed = hasAuth(opts);
    if (isAuthed) {
      await getClient(opts).totp.delete(id);
    } else {
      LocalStore.deleteTotp(id);
    }
    if (opts.json) {
      printJson({ success: true, id });
      return;
    }
    printSuccess(`Deleted TOTP entry "${id}"`);
  } catch (err) {
    printError(`Failed to delete TOTP "${id}"`, err);
    process.exit(1);
  }
}

